input.command:
cd /tmp
gen(){ node -e "
const total=$1;
let parts=[];let rem=total;
while(rem>0){ let n=Math.min(63,rem); parts.push('a'.repeat(n)); rem-=n; if(rem>0){rem-=1;} }
let s=parts.join('.');
process.stdout.write(s);
" ; }
for t in 251 252 253 254 255 256; do
  D=$(gen $t); echo "@@ len=${#D}"
  /workspace/dataset/test8_executable --domain "$D" --mode encode 2>/dev/null | tail -3
  echo "---- with trailing dot (len $((${#D}+1)))"
  /workspace/dataset/test8_executable --domain "$D." --mode encode 2>/dev/null | tail -3
  echo "======"
done

cd /tmp
g(){ node -e "
let n=$1; let parts=[];
for(let i=0;i<n;i++){let s='';for(let j=0;j<6;j++){s+=String.fromCodePoint(0x4e00+i*13+j*97);}parts.push(s);}
process.stdout.write(parts.join('.'));"; }
for n in 5 8 9 10 11; do
  D=$(g $n)
  echo "@@ nlabels=$n rawchars=$(node -e "process.stdout.write(String([...'$D'].length))")"
  /workspace/dataset/test8_executable --domain "$D" --mode encode 2>/dev/null | head -1 | cut -c1-120
done
